mapper.select:
select dt.seq as doctorSeq, dt.name as doctorName, ch.seq as hospitalSeq, ch.name as hospitalName, dp.seq as departmentSeq, dp.name as departmentName from cm_doctor dt left join cm_hospital ch on ch.seq = dt.hospital_seq and ch.is_enabled left join cm_department dp on dp.seq = dt.department_seq and dp.is_enabled
dt.is_enabled AND ch.seq = #{seq}
ORDER BY dt.seq DESC
